//! Round 9: the sidecar local-IPC record layer, handshake, payload shapes and telemetry
//! documents against vectors produced by EXECUTING the v0.1.4 sidecar crate's own Rust
//! (`fixtures/sidecar-oracle-vectors.json`, generated by the scratch harness in
//! `L9-evidence/r9-oracle-harness/` over an untouched copy of
//! `native/iroh_transport @ f4e366e9`). The round-8 Python generator's fixture stays as a
//! secondary cross-check (the last test).
use runtime::{
    sidecar_local::{
        ControlCallLimits, LocalProtocolError, RecordKind, SequenceGuard, client_hello,
        decode_record, derive_session_keys, encode_record, error_payload, hmac_sha256,
        parse_control_call, server_hello, verify_client_hello, verify_server_hello,
    },
    sidecar_telemetry::{
        ObservationState, TransportEvent, admission_counters_json, document_json, envelope_json,
        update_selected_path,
    },
};
use serde_json::Value;

fn oracle() -> Value {
    serde_json::from_str(include_str!("../fixtures/sidecar-oracle-vectors.json")).unwrap()
}
fn python() -> Value {
    serde_json::from_str(include_str!("../fixtures/sidecar-local-vectors.json")).unwrap()
}
fn unhex(text: &str) -> Vec<u8> {
    (0..text.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&text[i..i + 2], 16).unwrap())
        .collect()
}
fn arr<const N: usize>(text: &str) -> [u8; N] {
    unhex(text).try_into().unwrap()
}
fn text(value: &Value) -> &str {
    value.as_str().unwrap()
}
fn code_of(result: Result<[u8; 32], LocalProtocolError>) -> String {
    match result {
        Ok(nonce) => format!("ok:{}", hex(&nonce)),
        Err(LocalProtocolError::InvalidHello) => "parse_error".to_owned(),
        Err(other) => other.code().to_owned(),
    }
}
fn hex(bytes: &[u8]) -> String {
    bytes.iter().map(|b| format!("{b:02x}")).collect()
}

#[test]
fn provenance_names_the_pinned_oracle_and_an_executed_harness() {
    let v = oracle();
    assert!(text(&v["provenance"]["oracle"]).contains("f4e366e98a1f705dfaf182897044500d290dbd7f"));
    assert!(text(&v["provenance"]["method"]).contains("executing the oracle crate's own Rust"));
}

#[test]
fn hmac_and_handshake_match_the_oracle_including_hello_field_order_and_acceptance_rules() {
    let v = oracle();
    for case in v["hmac"].as_array().unwrap() {
        assert_eq!(
            hmac_sha256(
                &unhex(text(&case["key_hex"])),
                &unhex(text(&case["data_hex"]))
            )
            .to_vec(),
            unhex(text(&case["mac_hex"]))
        );
    }
    let h = &v["handshake"];
    let secret: [u8; 32] = arr(text(&h["secret_hex"]));
    let (cn, sn): ([u8; 32], [u8; 32]) = (
        arr(text(&h["client_nonce_hex"])),
        arr(text(&h["server_nonce_hex"])),
    );
    // Byte-identical hello objects (serde field order protocol, nonce, proof).
    assert_eq!(
        String::from_utf8(client_hello(&secret, &cn).unwrap()).unwrap(),
        text(&h["client_hello_json"])
    );
    assert_eq!(
        String::from_utf8(server_hello(&secret, &cn, &sn, text(&h["endpoint_id"])).unwrap())
            .unwrap(),
        text(&h["server_hello_json"])
    );
    let keys = derive_session_keys(&secret, &cn, &sn).unwrap();
    assert_eq!(
        keys.client_to_sidecar.to_vec(),
        unhex(text(&h["client_to_sidecar_hex"]))
    );
    assert_eq!(
        keys.sidecar_to_client.to_vec(),
        unhex(text(&h["sidecar_to_client_hex"]))
    );
    assert_eq!(
        derive_session_keys(&secret[..31], &cn, &sn)
            .unwrap_err()
            .code(),
        text(&h["derive_session_keys_31_byte_secret"])
    );
    // Acceptance rules, each outcome the oracle's.
    let good: Value = serde_json::from_str(text(&h["client_hello_json"])).unwrap();
    let with = |edit: &dyn Fn(&mut Value)| {
        let mut value = good.clone();
        edit(&mut value);
        serde_json::to_vec(&value).unwrap()
    };
    let expected = &h["client_verify"];
    let verify = |bytes: &[u8], key: &[u8]| code_of(verify_client_hello(bytes, key));
    assert_eq!(
        verify(text(&h["client_hello_json"]).as_bytes(), &secret),
        text(&expected["good"])
    );
    let alias = with(&|v| {
        let object = v.as_object_mut().unwrap();
        let nonce = object.remove("client_nonce").unwrap();
        let proof = object.remove("client_proof").unwrap();
        object.insert("nonce".into(), nonce);
        object.insert("proof".into(), proof);
    });
    assert_eq!(verify(&alias, &secret), text(&expected["alias_fields"]));
    assert_eq!(
        verify(text(&h["client_hello_json"]).as_bytes(), &[9; 32]),
        text(&expected["wrong_secret"])
    );
    assert_eq!(
        verify(&with(&|v| v["protocol"] = "x".into()), &secret),
        text(&expected["wrong_protocol"])
    );
    assert_eq!(
        verify(&with(&|v| v["client_nonce"] = "00".into()), &secret),
        text(&expected["short_nonce"])
    );
    let upper = text(&good["client_nonce"]).to_uppercase();
    assert_eq!(
        verify(
            &with(&|v| v["client_nonce"] = upper.clone().into()),
            &secret
        ),
        text(&expected["uppercase_nonce"]),
        "the oracle accepts an upper-case nonce whose proof was computed over the same bytes"
    );
    assert_eq!(
        verify(&with(&|v| v["x"] = 1.into()), &secret),
        text(&expected["unknown_field"])
    );
    assert_eq!(verify(b"not json", &secret), text(&expected["not_json"]));
    assert_eq!(
        verify(text(&h["client_hello_json"]).as_bytes(), &secret[..31]),
        text(&expected["secret_31_bytes"])
    );
    // Server side.
    let server = text(&h["server_hello_json"]).as_bytes();
    let outcome = |result: Result<([u8; 32], String), LocalProtocolError>| match result {
        Ok(_) => "ok".to_owned(),
        Err(LocalProtocolError::InvalidHello) => "parse_error".to_owned(),
        Err(other) => other.code().to_owned(),
    };
    let expected = &h["server_verify"];
    assert_eq!(
        outcome(verify_server_hello(server, &secret, &cn)),
        text(&expected["good"])
    );
    assert_eq!(
        outcome(verify_server_hello(server, &secret, &[8; 32])),
        text(&expected["wrong_client_nonce"])
    );
    let swapped = text(&h["server_hello_json"]).replace("\"public\"", "\"private\"");
    assert_eq!(
        outcome(verify_server_hello(swapped.as_bytes(), &secret, &cn)),
        text(&expected["swapped_endpoint"])
    );
    let alias = format!(
        "{{\"protocol\":\"mycelium.iroh_sidecar.local.v1\",\"nonce\":\"{}\",\"endpoint_id\":\"public\",\"proof\":\"{}\"}}",
        hex(&sn),
        text(&h["server_proof_hex"])
    );
    assert_eq!(
        outcome(verify_server_hello(alias.as_bytes(), &secret, &cn)),
        text(&expected["alias_fields"])
    );
}

#[test]
fn records_encode_to_the_oracle_bytes_and_negative_decodes_give_the_oracle_codes_in_order() {
    let v = oracle();
    let records = v["records"].as_array().unwrap();
    assert_eq!(records.len(), 38);
    for case in records {
        let kind = RecordKind::try_from(case["kind"].as_u64().unwrap() as u8).unwrap();
        let key: [u8; 32] = arr(text(&case["key_hex"]));
        let sequence = case["sequence"].as_u64().unwrap();
        let id: [u8; 16] = arr(text(&case["message_id_hex"]));
        let payload = unhex(text(&case["payload_hex"]));
        let encoded = encode_record(kind, sequence, id, &payload, &key).unwrap();
        assert_eq!(encoded, unhex(text(&case["encoded_hex"])), "{kind:?}");
        let mut guard = SequenceGuard::at(sequence);
        assert_eq!(
            decode_record(&encoded, &key, &mut guard).unwrap().payload,
            payload
        );
    }
    // The negative steps share one guard exactly as the oracle's harness ran them.
    let key: [u8; 32] = arr(text(&v["record_negative"]["key_hex"]));
    let mut shared = SequenceGuard::new();
    let fresh_for = |name: &str| -> Option<SequenceGuard> {
        matches!(name, "too_short" | "wrong_key_length" | "sequence_gap").then(SequenceGuard::new)
    };
    let mut fresh_ping = SequenceGuard::new();
    for case in v["record_negative_results"].as_array().unwrap() {
        let name = text(&case["name"]);
        if name.starts_with("encode_") {
            let result = match name {
                "encode_payload_over_cap" => encode_record(
                    RecordKind::Ping,
                    0,
                    [1; 16],
                    &vec![0; runtime::sidecar_local::LOCAL_MAX_PAYLOAD_BYTES + 1],
                    &key,
                ),
                "encode_payload_at_cap" => encode_record(
                    RecordKind::Ping,
                    0,
                    [1; 16],
                    &vec![0; runtime::sidecar_local::LOCAL_MAX_PAYLOAD_BYTES],
                    &key,
                ),
                "encode_key_16" => encode_record(RecordKind::Ping, 0, [1; 16], b"", &[1; 16]),
                other => panic!("unknown encode case {other}"),
            };
            let got = result.map_or_else(|e| e.code().to_owned(), |_| "ok".to_owned());
            assert_eq!(got, text(&case["outcome"]), "{name}");
            continue;
        }
        let input = unhex(text(&case["input_hex"]));
        let used_key: &[u8] = if name == "wrong_key_length" {
            &[0; 31]
        } else {
            &key
        };
        let mut local = fresh_for(name);
        let guard = if let Some(g) = local.as_mut() {
            g
        } else if name.starts_with("ping_") {
            &mut fresh_ping
        } else {
            &mut shared
        };
        let got = match decode_record(&input, used_key, guard) {
            Ok(record) => format!("ok:{}", record.kind as u8),
            Err(error) => error.code().to_owned(),
        };
        assert_eq!(got, text(&case["outcome"]), "{name}");
        assert_eq!(
            guard.next_expected().map(|n| n.to_string()),
            case["next_expected"].as_u64().map(|n| n.to_string()),
            "{name}: sequence position after the step"
        );
    }
}

#[test]
fn control_call_payloads_parse_to_the_oracle_verdicts() {
    let v = oracle();
    let limits = ControlCallLimits {
        ceiling_millis: v["constants"]["control_call_timeout_ceiling_ms"]
            .as_u64()
            .unwrap(),
        max_command_bytes: usize::try_from(
            v["constants"]["control_call_max_bytes"].as_u64().unwrap(),
        )
        .unwrap(),
    };
    let mut checked = 0;
    for (name, case) in v["control_call_results"].as_object().unwrap() {
        let Some(verdict) = case.get("verdict") else {
            continue;
        };
        if name == "invalid_point_control_call" {
            // Point validity needs the Iroh EndpointId type; pinned in the dispatcher tests.
            assert_eq!(verdict["err"], "invalid_control_destination");
            continue;
        }
        let payload = match case.get("input_hex") {
            Some(hex) => unhex(text(hex)),
            None => {
                // `destination + millis(8 BE) + 0x07 * n` large cases.
                let destination = unhex(text(&v["control_call_results"]["valid_destination_hex"]));
                let total = usize::try_from(case["input_len"].as_u64().unwrap()).unwrap();
                let millis = 1000_u64.to_be_bytes();
                [destination, millis.to_vec(), vec![7; total - 40]].concat()
            }
        };
        let got = parse_control_call(&payload, limits);
        match (&verdict["ok"], &verdict["err"]) {
            (Value::Null, err) => {
                assert_eq!(got.unwrap_err(), text(err), "{name}");
            }
            (ok, _) => {
                let call = got.unwrap_or_else(|e| panic!("{name}: {e}"));
                assert_eq!(
                    hex(&call.destination),
                    text(&ok["destination_hex"]),
                    "{name}"
                );
                assert_eq!(call.millis, ok["millis"].as_u64().unwrap(), "{name}");
                assert_eq!(
                    call.command.len() as u64,
                    ok["command_len"].as_u64().unwrap(),
                    "{name}"
                );
            }
        }
        checked += 1;
    }
    assert_eq!(checked, 15, "control-call verdict cases replayed");
}

fn state_from(value: &Value) -> ObservationState {
    ObservationState {
        path_class: text(&value["path"]).to_owned(),
        relay_identity: value["relay"].as_str().map(str::to_owned),
        cold_rtt_ms: value["cold"].as_f64(),
        rtt_samples_ms: value["rtt"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_f64().unwrap())
            .collect(),
        acknowledged_bytes: value["acked_bytes"].as_u64().unwrap(),
        acknowledged_elapsed_ms: value["acked_ms"].as_f64().unwrap(),
        attempts: value["attempts"].as_u64().unwrap(),
        failures: value["failures"].as_u64().unwrap(),
        connections_opened: value["opened"].as_u64().unwrap(),
        frames_sent: value["frames"].as_u64().unwrap(),
        reconnect_count: value["reconnects"].as_u64().unwrap(),
        selected_path_changes: value["changes"].as_u64().unwrap(),
        measured_at_unix_ms: value["at"].as_u64().unwrap(),
    }
}

#[test]
fn telemetry_documents_envelope_counters_events_and_error_payloads_match_the_oracle() {
    let v = oracle();
    let mut documents = Vec::new();
    for case in v["observations"].as_array().unwrap() {
        let state = state_from(&case["state"]);
        let json = document_json(
            text(&case["remote_endpoint_id"]),
            case["generation"].as_u64().unwrap(),
            Some(&state),
        );
        assert_eq!(json, text(&case["document_json"]), "{}", case["name"]);
        assert_eq!(
            document_json(
                text(&case["remote_endpoint_id"]),
                case["generation"].as_u64().unwrap(),
                None
            ),
            text(&case["document_json_without_state"]),
            "{}: a peer with no state",
            case["name"]
        );
        documents.push((text(&case["remote_endpoint_id"]).to_owned(), json));
    }
    documents.sort();
    let sorted: Vec<String> = documents.into_iter().map(|(_, json)| json).collect();
    assert_eq!(envelope_json(&sorted), text(&v["envelope_json"]));
    assert_eq!(
        admission_counters_json(5, 7, 2, 1_700_000_000_999),
        text(&v["admission_counters_json"])
    );
    for case in v["path_change_rule"].as_array().unwrap() {
        let mut state = ObservationState {
            path_class: text(&case["prior"]).to_owned(),
            ..ObservationState::default()
        };
        update_selected_path(&mut state, text(&case["new"]).to_owned(), None, None);
        assert_eq!(
            state.selected_path_changes,
            case["delta"].as_u64().unwrap(),
            "{case}"
        );
    }
    let mut state = ObservationState::default();
    for sample in 0..70 {
        update_selected_path(
            &mut state,
            "direct".to_owned(),
            None,
            Some(f64::from(sample)),
        );
    }
    update_selected_path(&mut state, "direct".to_owned(), None, Some(f64::NAN));
    update_selected_path(&mut state, "direct".to_owned(), None, Some(-1.0));
    update_selected_path(
        &mut state,
        "direct".to_owned(),
        Some("relay-x".to_owned()),
        None,
    );
    let window = &v["rtt_window"];
    assert_eq!(
        state.rtt_samples_ms.len() as u64,
        window["len"].as_u64().unwrap()
    );
    assert_eq!(
        state.rtt_samples_ms.front().copied(),
        window["first"].as_f64()
    );
    assert_eq!(
        state.rtt_samples_ms.back().copied(),
        window["last"].as_f64()
    );
    assert_eq!(state.cold_rtt_ms, window["cold"].as_f64());
    assert_eq!(
        state.relay_identity.as_deref(),
        window["relay_identity_after"].as_str()
    );

    let events = include_str!("../fixtures/sidecar-oracle-events.txt");
    let remote = "677a74d964e4a84ffa5025a8b5537b5c4a37ad6d146e854783ac734684a207c4";
    let lines: Vec<&str> = events.lines().collect();
    assert_eq!(TransportEvent::ConnectionOpened.line(remote, 3), lines[0]);
    assert_eq!(
        TransportEvent::PeerConnectDeadlineExceeded.line(remote, 3),
        lines[1]
    );
    for (code, expected) in v["error_payloads"].as_object().unwrap() {
        assert_eq!(error_payload(code), text(expected).as_bytes(), "{code}");
    }
}

#[test]
fn the_oracle_constants_the_port_hardcodes_are_the_oracle_values() {
    let c = &oracle()["constants"];
    assert_eq!(
        runtime::sidecar_local::LOCAL_MAX_PAYLOAD_BYTES as u64,
        c["local_max_payload_bytes"].as_u64().unwrap()
    );
    assert_eq!(
        runtime::sidecar_local::LOCAL_MAX_RECORD_BYTES as u64,
        c["local_max_record_bytes"].as_u64().unwrap()
    );
}

#[test]
fn the_round_eight_python_fixture_agrees_with_the_oracle_where_both_define_a_value() {
    let (o, p) = (oracle(), python());
    assert_eq!(o["hmac"], p["hmac"]);
    for key in [
        "client_proof_hex",
        "server_proof_hex",
        "client_to_sidecar_hex",
        "sidecar_to_client_hex",
    ] {
        assert_eq!(o["handshake"][key], p["handshake"][key], "{key}");
    }
    assert_eq!(o["records"], p["records"]);
    assert_eq!(o["path_change_rule"], p["path_change_rule"]);
    assert_eq!(o["admission_counters_json"], p["admission_counters_json"]);
    assert_eq!(o["error_payloads"], p["error_payloads"]);
    // The only disagreement: JSON object key order of the client hello (the generator sorted keys).
    assert_ne!(
        o["handshake"]["client_hello_json"],
        p["handshake"]["client_hello_json"]
    );
    // Observation documents agree once the endpoint id is substituted.
    for (a, b) in o["observations"]
        .as_array()
        .unwrap()
        .iter()
        .zip(p["observations"].as_array().unwrap())
    {
        let substituted = text(&a["document_json"]).replace(
            text(&a["remote_endpoint_id"]),
            text(&b["remote_endpoint_id"]),
        );
        assert_eq!(substituted, text(&b["document_json"]), "{}", a["name"]);
    }
}
